-- ERP 产品档案导入商城（租户 1，店铺 1）
-- 来源：防腐保温智慧平台_ERP数据.docx 的产品分类与产品档案总览。
-- 价格由元转换为分；库存采用文档中的期末库存，未提供的产品库存为 0。
-- “胶粘剂”在产品档案中出现，但分类总表未列，作为防腐材料下的补充分类保留。
SET NAMES utf8mb4;
START TRANSACTION;

UPDATE product_sku SET deleted=b'1', update_time=NOW(), updater='erp-import'
WHERE tenant_id=1 AND deleted=b'0';
UPDATE product_spu SET deleted=b'1', update_time=NOW(), updater='erp-import'
WHERE tenant_id=1 AND deleted=b'0';
UPDATE product_category SET deleted=b'1', update_time=NOW(), updater='erp-import'
WHERE tenant_id=1 AND deleted=b'0';

ON DUPLICATE KEY UPDATE parent_id=VALUES(parent_id),name=VALUES(name),pic_url=VALUES(pic_url),sort=VALUES(sort),status=VALUES(status),updater='erp-import',update_time=NOW(),deleted=b'0',tenant_id=1;

ON DUPLICATE KEY UPDATE shop_id=VALUES(shop_id),name=VALUES(name),keyword=VALUES(keyword),introduction=VALUES(introduction),description=VALUES(description),category_id=VALUES(category_id),pic_url=VALUES(pic_url),slider_pic_urls=VALUES(slider_pic_urls),sort=VALUES(sort),status=VALUES(status),spec_type=VALUES(spec_type),price=VALUES(price),market_price=VALUES(market_price),cost_price=VALUES(cost_price),stock=VALUES(stock),delivery_types=VALUES(delivery_types),updater='erp-import',update_time=NOW(),deleted=b'0',tenant_id=1;

